    cols=[j for j in range(w) if all(g[i][j]==div for i in range(h))]
    if rows and not cols:
        r0,r1=rows[0]+1,rows[1]; c0,c1=0,w
        rbounds=[0]+rows+[h]; cbounds=[0,w]
    elif cols and not rows:
        r0,r1=0,h; c0,c1=cols[0]+1,cols[1]
        rbounds=[0,h]; cbounds=[0]+cols+[w]
    else:
        rbounds=[0]+rows+[h]; cbounds=[0]+cols+[w]
        r0,r1=0,rows[0]; c0,c1=0,cols[0]
    src=[row[c0:c1] for row in g[r0:r1]]
    out=[row[:] for row in g]
    for a,b in zip(rbounds,rbounds[1:]):
        for e,f in zip(cbounds,cbounds[1:]):
            if (a,b)==(r0,r1) and (e,f)==(c0,c1): continue
            for i in range(a,b):
                for j in range(e,f):
                    out[i][j]=src[(i-r0)%len(src)][(j-c0)%len(src[0])]
