def transform(g):
    h=len(g); w=len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    maj=cnt.most_common(1)[0][0]
    div=None
    for c in cnt:
        if c==maj: continue
        if any(all(x==c for x in r) for r in g) or any(all(g[i][j]==c for i in range(h)) for j in range(w)):
            div=c; break
    rows=[i for i in range(h) if all(x==div for x in g[i])]
    cols=[j for j in range(w) if all(g[i][j]==div for i in range(h))]
    parallel = bool(rows) != bool(cols)
    if rows and not cols:
        r0,r1=rows[0]+1,rows[1]; c0,c1=0,w
        rbounds=[0]+rows+[h]; cbounds=[0,w]
    elif cols and not rows:
        r0,r1=0,h; c0,c1=cols[0]+1,cols[1]
        rbounds=[0,h]; cbounds=[0]+cols+[w]
    else:
        rbounds=[0]+rows+[h]; cbounds=[0]+cols+[w]
        r0,r1=0,rows[0]; c0,c1=0,cols[0]
    src=[row[c0:c1] for row in g[r0:r1]]
    out=[row[:] for row in g]
    for a,b in zip(rbounds,rbounds[1:]):
        for e,f in zip(cbounds,cbounds[1:]):
            if parallel:
                if (e>=c0 and f<=c1) and (a>=r0 and b<=r1): continue
            else:
                if b<=rows[0] and f<=cols[0]: continue
            for i in range(a,b):
                for j in range(e,f):
                    out[i][j]=src[(i-a)%len(src)][(j-e)%len(src[0])]
    return out

